@app.route("/csrf", methods=["GET", "POST"])
def csrf():
    if request.method == "POST":
        token = request.cookies.get("csrf_token")
        if token is None or token!= request.form["csrf_token"]:
            return "CSRF token invalid"
    return render_template("csrf.html")
@app.before_request
def before_request():
    if "csrf_token" not in session:
        session["csrf_token"] = app.secret_key
    token = session["csrf_token"]
    cookie_token = app.config["CSRF_COOKIE_NAME"] in request.cookies and request.cookies[app.config["CSRF_COOKIE_NAME"]]
    app.config["CSRF_COOKIE"] = cookie_token
    app.config["CSRF_TOKEN"] = token
@app.errorhandler(400)
def bad_request(e):
    return render_template("bad_request.html"), 400
if __name__ == "__main__":
    app.run(debug=True)
