import re
import random
import string
from collections import deque

def random_string(length):
    return ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(length))

def random_word(length):
    return random_string(length).capitalize()

def random_sentence(length):
    words = [random_word(random.randint(1, 15)) for _ in range(random.randint(2, 10))]
    sentence =''.join(words)
    if len(sentence) < length:
        sentence +='' + random_string(length - len(sentence) - 1)
    return sentence

def random_paragraph(length):
    sentences = [random_sentence(random.randint(5, 25)) for _ in range(random.randint(2, 5))]
    paragraph = '\n'.join(sentences)
    if len(paragraph) < length:
        paragraph += '\n' + random_string(length - len(paragraph) - 1)
    return paragraph

def random_text(length):
    if length < 20:
        return random_string(length)
    elif length < 200:
        return random_paragraph(length)
    else:
        return random_sentence(length)

def random_brackets(text):
    if not re.search('<|>' in text:
        text = '<>' + text
    open_brackets = random.randint(0, len(text) - 1)
    close_brackets = open_brackets + random.randint(0, len(text) - open_brackets - 1)
    return text[:open_brackets] + '<>' + text[open_brackets:close_brackets] + '<>' + text[close_brackets:]

def random_tags(text):
    if not re.search('<|>' in text:
        text = '<>' + text
    start = random.randint(0, len(text) - 1)
    end = start + random.randint(1, len(text) - start)
    return text[:start] + '<>' + text[start:end] + '<>' + text[end:]

