def random_escaped(text):
    text = text.replace('\\', '\\\\')
    text = text.replace('\n', '\\n')
    text = text.replace('\r', '\\r')
    text = text.replace('\t', '\\t')
    text = text.replace('\0', '\\0')
    return text

